const moduloDe=v=>(D.activities.find(a=>a.id===v)||{}).modulo||'resp';const ehOsso=k=>!!(ME&&ME.APOIO)&&!ME.APOIO[k]&&!!window.ESQ_GLTF&&(!!window.ESQ_GLTF.C.esqueleto[k]||!!window.ESQ_GLTF.C.esqueleto[k+'_d']);const ehMusculo=k=>!!(ME&&ME.APOIO&&ME.APOIO[k]);const ehNerv=k=>!!(D.NERV_KEYS&&D.NERV_KEYS.includes(k));const PREF={resp:'',esq:'esq-',nerv:'nerv-'};const prefMod=()=>PREF[S.modulo]||'';const desafioDe=m=>m==='esq'?'esqDesafio':m==='nerv'?'nervDesafio':'desafio';
