  const panel=this.textPlane(title,body,1.06,.86);panel.position.set(1.16,.3,-1.64);panel.rotation.y=-.6;this.ui.add(panel);
  const list=this.xrReport?[{label:'Voltar à atividade',cmd:'xr:reportclose'}]:this._acoes();const max=8,pages=Math.max(1,Math.ceil(list.length/max));this.uiPage=Math.min(this.uiPage,pages-1);list.slice(this.uiPage*max,(this.uiPage+1)*max).forEach((a,i)=>this.xrButton(a.label,a.cmd,1.16+(i%2?.25:-.25),-.22-Math.floor(i/2)*.15,.46,a.disabled));if(pages>1){this.xrButton('◀ Opções','xr:prev',.91,-.86,.46,this.uiPage===0);this.xrButton('Mais opções ▶','xr:next',1.41,-.86,.46,this.uiPage===pages-1);}
