  if(this.duasMaos&&this.duasMaos.obj===g){const dm=this.duasMaos;this.duasMaos=null;if(ctrl===dm.c2)return;/* soltou a primeira mão: a segunda passa a segurar */const grip=dm.c2.userData.grip||dm.c2;grip.attach(g);this.held.set(dm.c2,g);return;}
